         assertNull(childConf.get("abc"));
+        assertEquals("A", childConf.get("a"));
     }

     public void testSubworkflowLib() throws Exception {
@@ -684,7 +692,7 @@ public class TestSubWorkflowActionExecutor extends ActionExecutorTestCase {
