                 "            <name>foo3</name>" +
                 "            <value>foo3</value>" +
                 "        </property>" +
+                "        <property>" +
+                "            <name>foo4</name>" +
+                "            <value>actionconf</value>" +
+                "        </property>" +
                 "    </configuration>" +
                 "</global>" +
                 "<start to=\"subwf\"/>" +
