                 "<java>" +
-                "<job-tracker>" + getJobTrackerUri() + "</job-tracker>" +
-                "<name-node>" + getNameNodeUri() + "</name-node>" +
-                "<main-class>" + LauncherMainTester.class.getName() + "</main-class>" +
-                "<arg>exit0</arg>" +
+                "    <job-tracker>" + getJobTrackerUri() + "</job-tracker>" +
+                "    <name-node>" + getNameNodeUri() + "</name-node>" +
+                "        <configuration>" +
+                "            <property>" +
+                "                <name>foo4</name>" +
+                "                <value>subactionconf</value>" +
+                "            </property>" +
+                "        </configuration>" +
